arguments.command:
cd /src/mupdf && apply_patch <<'PATCH'
*** Begin Patch
*** Update File: source/pdf/pdf-cmap-parse.c
@@
 		if (buf->len / 2)
 		{
 			size_t i;
-			size_t len = fz_minz(buf->len / 2, nelem(dst));
+			size_t len = fz_minz(buf->len / 2, nelem(dst));
+			if (len != buf->len / 2)
+				fz_warn(ctx, "truncating bfRange array string in cmap %s", cmap->cmap_name);
 			for (i = 0; i < len; i++)
 				dst[i] = pdf_code_from_string(&buf->scratch[i * 2], 2);

-			pdf_map_one_to_many(ctx, cmap, lo, dst, buf->len / 2);
+			/* Pass the number of elements actually written into dst[]. */
+			pdf_map_one_to_many(ctx, cmap, lo, dst, len);
 		}
*** End Patch
PATCH

cd /src/mupdf && perl -0777 -i -pe 's/void
pdf_map_one_to_many\(fz_context \*ctx, pdf_cmap \*cmap, unsigned int low, int \*values, size_t len\)
\{
/void
pdf_map_one_to_many(fz_context *ctx, pdf_cmap *cmap, unsigned int low, int *values, size_t len)
{
	/* Never walk attacker-controlled lengths before validating. */
	if (len == 0)
		return;
	/* At most 2 input code units per output code point (surrogate pairs). */
	if (len > (size_t)PDF_MRANGE_CAP * 2)
	{
		fz_warn(ctx, "ignoring oversized one to many mapping in cmap %s", cmap->cmap_name);
		return;
	}
/sms' source/pdf/pdf-cmap.c && sed -n '710,770p' source/pdf/pdf-cmap.c

